#include <stdint.h>
#include <stdio.h>

extern volatile uint64_t tohost;

static inline uint64_t rdcycle(void) {
    uint64_t c;
    asm volatile("rdcycle %0" : "=r"(c));
    return c;
}

static inline uint64_t rdinstret(void) {
    uint64_t i;
    asm volatile("rdinstret %0" : "=r"(i));
    return i;
}

// Positive control test: measure branch misprediction penalty
uint64_t test_pos_control_correct(void) {
    uint64_t t0, t1;
    volatile int x = 0;
    // Train branch to be taken
    for (int i = 0; i < 50; i++) {
        asm volatile(
            "bnez %0, 1f\n"
            "1:\n"
            : : "r"(1)
        );
    }
    // Measure taken branch (correctly predicted)
    asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
    t0 = rdcycle();
    asm volatile(
        "bnez %0, 2f\n"
        "2:\n"
        : : "r"(1)
    );
    t1 = rdcycle();
    return t1 - t0;
}

uint64_t test_pos_control_mispredict(void) {
    uint64_t t0, t1;
    // Train branch to be taken
    for (int i = 0; i < 50; i++) {
        asm volatile(
            "bnez %0, 1f\n"
            "1:\n"
            : : "r"(1)
        );
    }
    // Measure not-taken branch (mispredicted!)
    asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
    t0 = rdcycle();
    asm volatile(
        "bnez %0, 2f\n"
        "2:\n"
        : : "r"(0)
    );
    t1 = rdcycle();
    return t1 - t0;
}

int main(void) {
    printf("Starting explore_bpu...\n");
    for (int trial = 0; trial < 5; trial++) {
        uint64_t c_correct = test_pos_control_correct();
        uint64_t c_mispredict = test_pos_control_mispredict();
        printf("Trial %d: correct=%lu, mispredict=%lu, penalty=%lu\n",
               trial, c_correct, c_mispredict, c_mispredict - c_correct);
    }
    tohost = 1;
    while (1) {}
}

