#include <stdint.h>
#include <stdio.h>

extern volatile uint64_t tohost;

static inline uint64_t rdcycle(void) {
    uint64_t c;
    asm volatile("rdcycle %0" : "=r"(c));
    return c;
}

// Macro for 8 conditional branches
// Each branch: if (arg != 0) goto target; target: fall-through
#define BR8(arg) \
    asm volatile( \
        "bnez %0, 10f\n" \
        "10: bnez %0, 11f\n" \
        "11: bnez %0, 12f\n" \
        "12: bnez %0, 13f\n" \
        "13: bnez %0, 14f\n" \
        "14: bnez %0, 15f\n" \
        "15: bnez %0, 16f\n" \
        "16: bnez %0, 17f\n" \
        "17:\n" \
        : : "r"(arg) \
    )

// History generator: executes N taken branches to set global history register (ghist)
static inline void set_history_A(void) {
    for (int i = 0; i < 16; i++) {
        asm volatile("bnez %0, 1f\n 1:\n" : : "r"(1));
    }
}

static inline void set_history_B(void) {
    for (int i = 0; i < 16; i++) {
        asm volatile("beqz %0, 1f\n 1:\n" : : "r"(0));
    }
}

// Function containing probe branches
__attribute__((noinline))
void probe_branches(int taken) {
    BR8(taken);
    BR8(taken);
}

int main(void) {
    printf("Starting frontend override test...\n");

    // Positive control: Compare fully predicted vs fully mispredicted
    printf("--- POSITIVE CONTROL TEST ---\n");
    for (int t = 0; t < 5; t++) {
        // Train 16 branches to be TAKEN
        for (int i = 0; i < 20; i++) {
            probe_branches(1);
        }
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t0 = rdcycle();
        probe_branches(1); // correctly predicted taken
        uint64_t t1 = rdcycle();

        // Train 16 branches to be TAKEN
        for (int i = 0; i < 20; i++) {
            probe_branches(1);
        }
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t2 = rdcycle();
        probe_branches(0); // mispredicted (not-taken)!
        uint64_t t3 = rdcycle();

        printf("PosCtrl %d: pred_taken=%lu, mispred_not_taken=%lu, delta=%lu\n",
               t, t1 - t0, t3 - t2, (t3 - t2) - (t1 - t0));
    }

    // Now test Stage Agreement vs Frontend Override
    printf("--- STAGE OVERRIDE TEST ---\n");
    for (int t = 0; t < 5; t++) {
        // 1. Train TAGE under History A: probe_branches is NOT TAKEN
        for (int i = 0; i < 20; i++) {
            set_history_A();
            probe_branches(0);
        }

        // Measure Condition A: Baseline (History A, both BIM and TAGE predict NOT TAKEN)
        set_history_A();
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t0 = rdcycle();
        probe_branches(0);
        uint64_t t1 = rdcycle();

        // 2. Intervening workload: Train BIM to TAKEN under History B
        for (int i = 0; i < 20; i++) {
            set_history_B();
            probe_branches(1);
        }
        // Now restore TAGE under History A with NOT TAKEN, but BIM has been disturbed
        // Wait, if we run under History A again with probe_branches(0),
        // let's see what happens if BIM was trained to 1:
        set_history_A();
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t2 = rdcycle();
        probe_branches(0);
        uint64_t t3 = rdcycle();

        printf("Override %d: agree=%lu, override_probe=%lu, diff=%lu\n",
               t, t1 - t0, t3 - t2, (t3 - t2) > (t1 - t0) ? (t3 - t2) - (t1 - t0) : 0);
    }

    tohost = 1;
    while (1) {}
}

