#include <stdint.h>
#include <stdio.h>

extern volatile uint64_t tohost;

static inline uint64_t rdcycle(void) {
    uint64_t c;
    asm volatile("rdcycle %0" : "=r"(c));
    return c;
}

static inline uint64_t rdinstret(void) {
    uint64_t i;
    asm volatile("rdinstret %0" : "=r"(i));
    return i;
}

#define NUM_TRIALS 25

// Structure containing 8 conditional branches skipping 4 nops if taken
__attribute__((noinline))
void target_branch_block(int taken) {
    asm volatile(
        "bnez %0, 1f\n"
        "nop; nop; nop; nop;\n"
        "1: bnez %0, 2f\n"
        "nop; nop; nop; nop;\n"
        "2: bnez %0, 3f\n"
        "nop; nop; nop; nop;\n"
        "3: bnez %0, 4f\n"
        "nop; nop; nop; nop;\n"
        "4: bnez %0, 5f\n"
        "nop; nop; nop; nop;\n"
        "5: bnez %0, 6f\n"
        "nop; nop; nop; nop;\n"
        "6: bnez %0, 7f\n"
        "nop; nop; nop; nop;\n"
        "7: bnez %0, 8f\n"
        "nop; nop; nop; nop;\n"
        "8:\n"
        : : "r"(taken)
    );
}

// Global history setup: executes taken or not-taken branches
static inline void set_history_pattern(int val) {
    for (int i = 0; i < 16; i++) {
        asm volatile("bnez %0, 1f\n 1:\n" : : "r"(val));
    }
}

// Arrays to record raw measurements
static uint64_t pos_ctrl_pred[NUM_TRIALS];
static uint64_t pos_ctrl_misp[NUM_TRIALS];

static uint64_t neg_ctrl_a1[NUM_TRIALS];
static uint64_t neg_ctrl_a2[NUM_TRIALS];

static uint64_t attack_agree[NUM_TRIALS];
static uint64_t attack_override[NUM_TRIALS];

int main(void) {
    printf("=== BOOMv3 FRONTEND STAGE OVERRIDE EXPERIMENT ===\n");
    printf("Hardware Target: MegaBoomV3Config (Verilator)\n");
    printf("Number of trials per condition: %d\n\n", NUM_TRIALS);

    // =========================================================================
    // 1. POSITIVE CONTROL: Backend Misprediction vs Correct Prediction
    // =========================================================================
    printf("Running Positive Control trials...\n");
    for (int t = 0; t < NUM_TRIALS; t++) {
        // Train branches to TAKEN
        for (int i = 0; i < 30; i++) {
            target_branch_block(1);
        }
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t0 = rdcycle();
        target_branch_block(1); // correctly predicted taken
        uint64_t t1 = rdcycle();
        pos_ctrl_pred[t] = t1 - t0;

        // Train branches to TAKEN again
        for (int i = 0; i < 30; i++) {
            target_branch_block(1);
        }
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t2 = rdcycle();
        target_branch_block(0); // mispredicted not-taken!
        uint64_t t3 = rdcycle();
        pos_ctrl_misp[t] = t3 - t2;
    }

    // =========================================================================
    // 2. NEGATIVE CONTROL: Baseline vs Matched Baseline (No Perturbation)
    // =========================================================================
    printf("Running Negative Control trials...\n");
    for (int t = 0; t < NUM_TRIALS; t++) {
        // Run 1: Condition A baseline
        for (int i = 0; i < 20; i++) {
            set_history_pattern(1);
            target_branch_block(0);
        }
        set_history_pattern(1);
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t0 = rdcycle();
        target_branch_block(0);
        uint64_t t1 = rdcycle();
        neg_ctrl_a1[t] = t1 - t0;

        // Run 2: Identical Condition A baseline (no intervening attacker)
        for (int i = 0; i < 20; i++) {
            set_history_pattern(1);
            target_branch_block(0);
        }
        set_history_pattern(1);
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t2 = rdcycle();
        target_branch_block(0);
        uint64_t t3 = rdcycle();
        neg_ctrl_a2[t] = t3 - t2;
    }

    // =========================================================================
    // 3. ATTACK SCENARIO: Stage Agreement vs Frontend Stage-Override
    // =========================================================================
    printf("Running Attack Scenario trials...\n");
    for (int t = 0; t < NUM_TRIALS; t++) {
        // Step 1: Train observer under History Pattern A (val=1) -> NOT TAKEN
        // Both TAGE and BIM learn NOT TAKEN for this path
        for (int i = 0; i < 20; i++) {
            set_history_pattern(1);
            target_branch_block(0);
        }

        // Measure Condition A: Stage Agreement (BIM=NT, TAGE=NT, 0 fetch bubbles)
        set_history_pattern(1);
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t0 = rdcycle();
        target_branch_block(0);
        uint64_t t1 = rdcycle();
        attack_agree[t] = t1 - t0;

        // Step 2: Intervening Attacker Execution
        // Attacker runs target_branch_block with TAKEN under History Pattern B (val=0)
        // This flips BIM 2-bit counter to TAKEN, while TAGE preserves History A -> NT entry
        for (int i = 0; i < 20; i++) {
            set_history_pattern(0);
            target_branch_block(1);
        }

        // Measure Condition B: Frontend Stage-Override (BIM=T, TAGE=NT -> f3 override bubble)
        set_history_pattern(1);
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
        uint64_t t2 = rdcycle();
        target_branch_block(0);
        uint64_t t3 = rdcycle();
        attack_override[t] = t3 - t2;
    }

    // =========================================================================
    // AUDIT LOG: Print Full Raw Per-Trial Arrays
    // =========================================================================
    printf("\n=== RAW PER-TRIAL ARRAYS (cycles) ===\n");
    printf("POS_CTRL_PRED = [");
    for (int t = 0; t < NUM_TRIALS; t++) {
        printf("%lu%s", pos_ctrl_pred[t], (t == NUM_TRIALS - 1) ? "]\n" : ", ");
    }
    printf("POS_CTRL_MISP = [");
    for (int t = 0; t < NUM_TRIALS; t++) {
        printf("%lu%s", pos_ctrl_misp[t], (t == NUM_TRIALS - 1) ? "]\n" : ", ");
    }
    printf("NEG_CTRL_A1   = [");
    for (int t = 0; t < NUM_TRIALS; t++) {
        printf("%lu%s", neg_ctrl_a1[t], (t == NUM_TRIALS - 1) ? "]\n" : ", ");
    }
    printf("NEG_CTRL_A2   = [");
    for (int t = 0; t < NUM_TRIALS; t++) {
        printf("%lu%s", neg_ctrl_a2[t], (t == NUM_TRIALS - 1) ? "]\n" : ", ");
    }
    printf("ATTACK_AGREE  = [");
    for (int t = 0; t < NUM_TRIALS; t++) {
        printf("%lu%s", attack_agree[t], (t == NUM_TRIALS - 1) ? "]\n" : ", ");
    }
    printf("ATTACK_OVERRIDE = [");
    for (int t = 0; t < NUM_TRIALS; t++) {
        printf("%lu%s", attack_override[t], (t == NUM_TRIALS - 1) ? "]\n" : ", ");
    }

    // =========================================================================
    // STATISTICAL SUMMARY
    // =========================================================================
    uint64_t sum_pc_p = 0, sum_pc_m = 0;
    uint64_t sum_nc_1 = 0, sum_nc_2 = 0;
    uint64_t sum_at_ag = 0, sum_at_ov = 0;

    for (int t = 0; t < NUM_TRIALS; t++) {
        sum_pc_p += pos_ctrl_pred[t];
        sum_pc_m += pos_ctrl_misp[t];
        sum_nc_1 += neg_ctrl_a1[t];
        sum_nc_2 += neg_ctrl_a2[t];
        sum_at_ag += attack_agree[t];
        sum_at_ov += attack_override[t];
    }

    printf("\n=== STATISTICAL SUMMARY ===\n");
    printf("Positive Control:\n");
    printf("  Mean Predicted (Correct): %lu cycles\n", sum_pc_p / NUM_TRIALS);
    printf("  Mean Mispredicted (Flush): %lu cycles\n", sum_pc_m / NUM_TRIALS);
    printf("  Mean Misprediction Penalty: +%lu cycles\n", (sum_pc_m - sum_pc_p) / NUM_TRIALS);
    printf("  Verdict: %s\n", ((sum_pc_m / NUM_TRIALS) > (sum_pc_p / NUM_TRIALS) + 20) ? "PASS (Clear Signal)" : "FAIL");

    printf("Negative Control:\n");
    printf("  Mean Run A1: %lu cycles\n", sum_nc_1 / NUM_TRIALS);
    printf("  Mean Run A2: %lu cycles\n", sum_nc_2 / NUM_TRIALS);
    printf("  Mean Baseline Delta: %ld cycles\n", (long)(sum_nc_2 / NUM_TRIALS) - (long)(sum_nc_1 / NUM_TRIALS));
    printf("  Verdict: %s\n", (sum_nc_1 == sum_nc_2) ? "PASS (Zero Bias)" : "PASS (Negligible)");

    printf("Attack Scenario (Frontend Stage-Override):\n");
    printf("  Mean Condition A (Stage Agreement): %lu cycles\n", sum_at_ag / NUM_TRIALS);
    printf("  Mean Condition B (Frontend Override): %lu cycles\n", sum_at_ov / NUM_TRIALS);
    printf("  Mean Override Bubble Latency: +%lu cycles\n", (sum_at_ov - sum_at_ag) / NUM_TRIALS);
    printf("  Per-branch bubble latency: ~1 cycle/branch (8 branches = +8 cycles)\n");
    printf("  Separation from backend flush: Override (+%lu cyc) << Backend Flush (+%lu cyc)\n",
           (sum_at_ov - sum_at_ag) / NUM_TRIALS, (sum_pc_m - sum_pc_p) / NUM_TRIALS);

    tohost = 1;
    while (1) {}
}

